 String key(Varnode v,int depth){if(v==null)return "NONE";Set<Long>cs=constants(v,0,new HashSet<>());if(cs.size()==1)return "c"+Long.toHexString(cs.iterator().next());if(depth>10)return v.toString();PcodeOp d=v.getDef();if(d==null)return v.toString();if(d.getOpcode()==PcodeOp.COPY||d.getOpcode()==PcodeOp.CAST)return key(d.getInput(0),depth+1);String b=d.getMnemonic()+"(";for(int i=0;i<d.getNumInputs();i++)b+=(i>0?",":"")+key(d.getInput(i),depth+1);return b+")";}
